format.typst_code:
#set page(width: 80mm, height: auto, margin: 4mm)
#set text(font: "Inter", size: 8pt)
#set par(justify: false, leading: 0.55em)
#align(center)[
  #text(size: 12pt, weight: "bold")[POS RECEIPT]
  #line(length: 100%)
  #doc.name
]
#grid(columns: (1fr, auto), gutter: 2mm,
  [Date], [#doc.posting_date],
  [Time], [#doc.posting_time],
  [Customer], [#doc.customer_name],
)
#line(length: 100%, stroke: 0.4pt)
#for item in doc.items {
  grid(columns: (1fr, auto), gutter: 2mm,
    [#item.item_name], [#item.amount],
    [#item.qty × #item.rate], []
  )
}
#line(length: 100%, stroke: 0.4pt)
#grid(columns: (1fr, auto), gutter: 2mm,
  [Grand Total], [#text(weight: "bold")[#doc.grand_total]],
  [Paid], [#doc.paid_amount],
)
#if "payments" in doc {
  line(length: 100%, stroke: 0.4pt)
  for payment in doc.payments {
    grid(columns: (1fr, auto), gutter: 2mm,
      [#payment.mode_of_payment], [#payment.amount]
    )
  }
}
#align(center)[
  #line(length: 100%)
  Thank you
]
